  `pending_rows` int DEFAULT NULL,
  `config_json` text,
  `mapping_json` text,
  `notes_json` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


